void app_ble_export_on_send_data_complete(uint8_t conn_id,
                                          T_SERVER_ID service_id,
                                          uint16_t attrib_idx,
                                          uint16_t cause,
                                          uint16_t credits)
{
    if (!zy100_ble_ctrl_service_is_export_attrib(service_id, attrib_idx))
    {
        return;
    }

#if ZY100_ONLINE_STREAM_ENABLE
    if (zy100_online_stream_active() ||
        zy100_online_stream_end_wait_ack())
    {
        zy100_online_stream_note_send_complete(conn_id, cause, credits);
        return;
    }
#endif

    app_ble_export_controller_on_send_data_complete(conn_id,
                                                    service_id,
                                                    attrib_idx,
                                                    cause,
                                                    credits);
    app_ble_offline_v2_sync_on_send_complete(conn_id, cause);
}

