static const char *app_task_multi_session_alloc_status_name(
    zy100_session_alloc_status_t status)
{
    switch (status)
    {
    case ZY100_SESSION_ALLOC_OK:
        return "none";
    case ZY100_SESSION_ALLOC_DIR_FULL:
        return "dir_full";
    case ZY100_SESSION_ALLOC_RAW_FULL:
        return "raw_full";
    case ZY100_SESSION_ALLOC_SUMMARY_FULL:
        return "summary_full";
    case ZY100_SESSION_ALLOC_EVENT_FULL:
        return "event_full";
    case ZY100_SESSION_ALLOC_FLASH_NOT_READY:
        return "flash_not_ready";
    case ZY100_SESSION_ALLOC_BAD_STATE:
    default:
        return "bad_state";
    }
}

static const char *app_task_multi_session_snapshot_error(
    bool refresh_ok,
    const zy100_session_readiness_t *snapshot)
{
    if (!refresh_ok || (snapshot == NULL) || !snapshot->valid)
    {
        return "scan_failed";
    }
    if (snapshot->storage_dirty_need_clear)
    {
        return "storage_dirty";
    }
    if (snapshot->clear_active)
    {
        return "clear_active";
    }
    if (snapshot->expc_without_rcld)
    {
        return "expc_without_rcld";
    }
    if (snapshot->reclaim_active)
    {
        return "reclaim_active";
    }
    if (!snapshot->can_start_next)
    {
        return app_task_multi_session_alloc_status_name(
                   snapshot->last_alloc_status);
    }
    return "none";
}

void app_task_multi_session_refresh_readiness(const char *reason)
{
    zy100_session_readiness_t snapshot;
    app_ble_export_port_storage_state_t next;
    const char *use_reason = (reason != NULL) ? reason : "unknown";
    const char *error_reason;
    uint64_t now_ms = os_sys_time_get();
    bool refresh_ok;
    bool changed;
    bool runtime_busy =
        (s_app_v1_state == APP_V1_STATE_CAPTURING) ||
        imu_fifo_drain_test_is_active() ||
        imu_fifo_drain_test_is_busy() ||
        imu_fifo_drain_test_is_stop_in_progress() ||
        imu_fifo_drain_test_is_start_pending();

    if (runtime_busy)
    {
        if (!s_multi_session_ready_cache.runtime_busy ||
            ((now_ms - s_multi_session_runtime_guard_last_ms) >= 1000ULL))
        {
            s_multi_session_runtime_guard_last_ms = now_ms;
#if ZY100_LOG_VERBOSE_DEFAULT
            DBG_DIRECT("[CAP_RUNTIME_GUARD] skip_readiness_refresh reason=capture_active caller=%s",
                       use_reason);
#endif
        }
        s_multi_session_ready_cache.runtime_busy = true;
        s_multi_session_ready_cache.can_start_next = false;
        s_multi_session_ready_cache.last_refresh_reason = use_reason;
        s_multi_session_ready_cache.last_error_reason = "capture_active";
        s_multi_session_ready_cache.last_update_ms = now_ms;
        return;
    }

    memset(&snapshot, 0, sizeof(snapshot));
    refresh_ok = zy100_session_dir_refresh_readiness(&snapshot);
    error_reason = app_task_multi_session_snapshot_error(refresh_ok, &snapshot);

    memset(&next, 0, sizeof(next));
    next.valid = refresh_ok && snapshot.valid;
    next.storage_dirty_need_clear = snapshot.storage_dirty_need_clear;
    next.reclaim_active = snapshot.reclaim_active;
    next.clear_active = snapshot.clear_active;
    next.expc_without_rcld = snapshot.expc_without_rcld;
    next.runtime_busy = false;
    next.dirty = !next.valid ||
                 next.storage_dirty_need_clear ||
                 next.expc_without_rcld;
    next.pending_count = next.valid ? snapshot.pending_count : 0U;
    next.can_start_next = next.valid &&
                          snapshot.can_start_next &&
                          !next.storage_dirty_need_clear &&
                          !next.clear_active &&
                          !next.reclaim_active &&
                          !next.expc_without_rcld;
    next.reclaim_session_uid = snapshot.reclaim_session_uid;
    next.last_alloc_status = snapshot.last_alloc_status;
    next.remaining_percent = snapshot.remaining_percent;
    next.last_refresh_reason = use_reason;
    next.last_error_reason = error_reason;
    next.last_update_ms = now_ms;
    next.generation = s_multi_session_ready_cache.generation + 1U;

    changed =
        (s_multi_session_ready_cache.valid != next.valid) ||
        (s_multi_session_ready_cache.dirty != next.dirty) ||
        (s_multi_session_ready_cache.pending_count != next.pending_count) ||
        (s_multi_session_ready_cache.can_start_next != next.can_start_next) ||
        (s_multi_session_ready_cache.storage_dirty_need_clear != next.storage_dirty_need_clear) ||
        (s_multi_session_ready_cache.reclaim_active != next.reclaim_active) ||
        (s_multi_session_ready_cache.clear_active != next.clear_active) ||
        (s_multi_session_ready_cache.expc_without_rcld != next.expc_without_rcld) ||
        (s_multi_session_ready_cache.runtime_busy != next.runtime_busy) ||
        (s_multi_session_ready_cache.reclaim_session_uid != next.reclaim_session_uid) ||
        (s_multi_session_ready_cache.last_alloc_status != next.last_alloc_status) ||
        (s_multi_session_ready_cache.remaining_percent != next.remaining_percent) ||
        (s_multi_session_ready_cache.last_error_reason == NULL) ||
        (strcmp(s_multi_session_ready_cache.last_error_reason,
                next.last_error_reason) != 0);

    s_multi_session_ready_cache = next;
    if (next.valid && (next.pending_count == 0U))
    {
        app_task_flash_full_wait_upload_gate_clear(use_reason);
    }
    if ((s_wake_boot_capture_block ==
         APP_WAKE_BOOT_CAPTURE_BLOCK_FLASH_CRITICAL) &&
        !s_wake_boot_sequence_active &&
        next.valid &&
        !next.dirty &&
        (next.pending_count == 0U) &&
        next.can_start_next &&
        (next.remaining_percent > (uint8_t)APP_WAKE_BOOT_FLASH_CRIT_PERCENT))
    {
        s_wake_boot_capture_block = APP_WAKE_BOOT_CAPTURE_BLOCK_NONE;
        DBG_DIRECT("[WAKE_BOOT] flash_critical_unlock remaining=%u reason=%s",
                   next.remaining_percent,
                   use_reason);
    }
    if (s_runtime_flash_critical_locked &&
        next.valid &&
        !next.dirty &&
        (next.pending_count == 0U) &&
        next.can_start_next &&
        (next.remaining_percent > (uint8_t)APP_WAKE_BOOT_FLASH_CRIT_PERCENT))
    {
        app_task_runtime_flash_critical_unlock(use_reason);
    }

    if (changed || !next.valid)
    {
#if ZY100_LOG_VERBOSE_DEFAULT
        DBG_DIRECT("[CR] c g=%lu v=%u d=%u p=%lu n=%u sd=%u r=%u c=%u e=%u rs=%s err=%s",
                   (unsigned long)next.generation,
                   next.valid ? 1U : 0U,
                   next.dirty ? 1U : 0U,
                   (unsigned long)next.pending_count,
                   next.can_start_next ? 1U : 0U,
                   next.storage_dirty_need_clear ? 1U : 0U,
                   next.reclaim_active ? 1U : 0U,
                   next.clear_active ? 1U : 0U,
                   next.expc_without_rcld ? 1U : 0U,
                   use_reason,
                   error_reason);
#else
        if ((!next.valid) || next.dirty || (next.pending_count != 0U) || (!next.can_start_next))
        {
            DBG_DIRECT("[CAP_READY] v=%u d=%u p=%lu n=%u rs=%s err=%s",
                       next.valid ? 1U : 0U,
                       next.dirty ? 1U : 0U,
                       (unsigned long)next.pending_count,
                       next.can_start_next ? 1U : 0U,
                       use_reason,
                       error_reason);
        }
#endif
    }
}

uint32_t app_task_multi_session_cached_pending_count(void)
{
    return s_multi_session_ready_cache.valid ?
           s_multi_session_ready_cache.pending_count : 0U;
}

static bool app_task_flash_full_wait_stop_reason(
    imu_fifo_drain_test_stop_reason_t stop_reason)
{
    return (stop_reason == IMU_FIFO_DRAIN_TEST_STOP_REASON_FLASH_95_PERCENT) ||
           (stop_reason == IMU_FIFO_DRAIN_TEST_STOP_REASON_EDGE_FULL);
}

static bool app_task_flash_full_wait_upload_gate_active(void)
{
    return s_flash_full_wait_upload_gate;
}

static void app_task_flash_full_wait_upload_gate_clear(const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "unknown";

    if (!s_flash_full_wait_upload_gate)
    {
        return;
    }

    s_flash_full_wait_upload_gate = false;
    led_release(LED_OWNER_FLASH_FULL_WAIT_UPLOAD);
    if ((s_app_v1_state == APP_V1_STATE_EXPORT_WAIT_START) &&
        app_task_flash_full_wait_stop_reason(imu_fifo_drain_test_last_stop_reason()))
    {
        s_app_v1_state = s_multi_session_ready_cache.can_start_next ?
                         APP_V1_STATE_WAIT_START :
                         APP_V1_STATE_STORAGE_NEED_REPAIR;
    }
    DBG_DIRECT("[FLASH_FULL_WAIT] gate=0 reason=%s", use_reason);
}

static bool app_task_flash_full_wait_upload_gate_arm(
    imu_fifo_drain_test_stop_reason_t stop_reason,
    const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "unknown";

    if (!app_task_flash_full_wait_stop_reason(stop_reason) ||
        !imu_fifo_drain_test_final_edge_export_ready() ||
        !s_multi_session_ready_cache.valid ||
        (s_multi_session_ready_cache.pending_count == 0U))
    {
        return false;
    }

    if (!s_flash_full_wait_upload_gate)
    {
        DBG_DIRECT("[FLASH_FULL_WAIT] gate=1 reason=%s stop_reason=%u pending=%lu",
                   use_reason,
                   (uint32_t)stop_reason,
                   (unsigned long)s_multi_session_ready_cache.pending_count);
    }
    s_flash_full_wait_upload_gate = true;
    return true;
}
