static bool app_led_request_charge_not_full(led_owner_t owner,
                                            uint8_t priority,
                                            bool *sequence_requested)
{
    bool request_sequence = !s_charge_logo_chase_played_for_present;
    bool request_ok;

    if (sequence_requested != NULL)
    {
        *sequence_requested = request_sequence;
    }

    if (request_sequence)
    {
        request_ok = app_led_request_charge_sequence(owner, priority);
        if (request_ok)
        {
            s_charge_logo_chase_played_for_present = true;
            led_charge_chase_once_mark_consumed();
        }
        return request_ok;
    }

    return app_led_request_charge_breath(owner, priority);
}
