static void app_task_active_ble_wait_reset(const char *reason)
{
#if !ZY100_LED_LOG_ENABLE
    (void)app_task_active_ble_wait_state_name;
#endif
    if (s_active_ble_wait_state != APP_ACTIVE_BLE_WAIT_IDLE)
    {
        APP_LED_LOG("[ACTIVE_BLE_WAIT] reset state=%s reason=%s",
                    app_task_active_ble_wait_state_name(s_active_ble_wait_state),
                    (reason != NULL) ? reason : "inactive");
    }

    led_release(LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT);
    s_active_ble_wait_state = APP_ACTIVE_BLE_WAIT_IDLE;
    s_active_ble_wait_start_ms = 0ULL;
}

static void app_task_active_ble_wait_complete(const char *reason)
{
    if (s_active_ble_wait_state != APP_ACTIVE_BLE_WAIT_DONE)
    {
        APP_LED_LOG("[ACTIVE_BLE_WAIT] done state=%s reason=%s",
                    app_task_active_ble_wait_state_name(s_active_ble_wait_state),
                    (reason != NULL) ? reason : "done");
    }

    led_release(LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT);
    s_active_ble_wait_state = APP_ACTIVE_BLE_WAIT_DONE;
    s_active_ble_wait_start_ms = 0ULL;
}

static void app_task_active_ble_wait_complete_if_started(const char *reason)
{
    if (s_active_ble_wait_state != APP_ACTIVE_BLE_WAIT_IDLE)
    {
        app_task_active_ble_wait_complete(reason);
    }
}

static void app_task_active_ble_wait_poll(uint64_t runtime_ms)
{
    led_owner_t owner;

    if (app_device_pairing_window_active() || app_user_reset_active()) return;

    if (!app_task_active_ble_wait_context_active())
    {
        app_task_active_ble_wait_reset("context_inactive");
        return;
    }

    if (s_active_ble_wait_state == APP_ACTIVE_BLE_WAIT_DONE)
    {
        return;
    }

    if (app_ble_power_is_connected())
    {
        app_task_active_ble_wait_complete("ble_connected");
        return;
    }

    if (app_task_capture_is_active() ||
        zy100_offline_v2_capture_active() ||
        app_task_training_start_led_gate_is_active())
    {
        app_task_active_ble_wait_complete("capture_active");
        return;
    }

    switch (s_active_ble_wait_state)
    {
    case APP_ACTIVE_BLE_WAIT_IDLE:
        s_active_ble_wait_start_ms = runtime_ms;
        s_active_ble_wait_state = APP_ACTIVE_BLE_WAIT_ARMED;
        APP_LED_LOG("[ACTIVE_BLE_WAIT] arm timeout_ms=%u",
                    (uint32_t)APP_ACTIVE_BLE_WAIT_TIMEOUT_MS);
        break;

    case APP_ACTIVE_BLE_WAIT_ARMED:
        if ((runtime_ms - s_active_ble_wait_start_ms) <
            (uint64_t)APP_ACTIVE_BLE_WAIT_TIMEOUT_MS)
        {
            break;
        }

        if (!app_led_request_notify_blink(LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT,
                                          LED_PRIORITY_ACTIVE_BLE_WAIT_TIMEOUT,
                                          LED_PATTERN_COLOR_BLUE,
                                          APP_ACTIVE_BLE_WAIT_ON_MS,
                                          APP_ACTIVE_BLE_WAIT_OFF_MS,
                                          (uint8_t)APP_ACTIVE_BLE_WAIT_CYCLES,
                                          true))
        {
            APP_LED_LOG("[ACTIVE_BLE_WAIT][WARN] request_failed");
            app_task_active_ble_wait_complete("request_failed");
            break;
        }

        owner = led_current_owner();
        if (owner != LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT)
        {
            APP_LED_LOG("[ACTIVE_BLE_WAIT] suppressed owner=%u",
                        (uint32_t)owner);
            app_task_active_ble_wait_complete("covered");
            break;
        }

        s_active_ble_wait_state = APP_ACTIVE_BLE_WAIT_LED_ACTIVE;
        APP_LED_LOG("[ACTIVE_BLE_WAIT] start on_ms=%u off_ms=%u cycles=%u",
                    (uint32_t)APP_ACTIVE_BLE_WAIT_ON_MS,
                    (uint32_t)APP_ACTIVE_BLE_WAIT_OFF_MS,
                    (uint32_t)APP_ACTIVE_BLE_WAIT_CYCLES);
        break;

    case APP_ACTIVE_BLE_WAIT_LED_ACTIVE:
        if (!led_owner_is_active(LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT))
        {
            app_task_active_ble_wait_complete("blink_done");
            break;
        }

        owner = led_current_owner();
        if (owner != LED_OWNER_ACTIVE_BLE_WAIT_TIMEOUT)
        {
            APP_LED_LOG("[ACTIVE_BLE_WAIT] overridden owner=%u",
                        (uint32_t)owner);
            app_task_active_ble_wait_complete("covered");
        }
        break;

    case APP_ACTIVE_BLE_WAIT_DONE:
    default:
        break;
    }
}
#else
#define app_task_active_ble_wait_poll(runtime_ms) \
    do { (void)(runtime_ms); } while (0)
#define app_task_active_ble_wait_complete(reason) \
    do { (void)(reason); } while (0)
#define app_task_active_ble_wait_complete_if_started(reason) \
    do { (void)(reason); } while (0)
#endif

