static void app_task_device_set_state(app_device_gate_state_t state,
                                      const char *reason)
{
    if (s_device_gate_state != state)
    {
        DBG_DIRECT("[DEVICE_GATE] state=%s first_power_seen=%u pairing_bonded=%u reason=%s",
                   app_task_device_gate_state_name(state),
                   s_device_first_power_seen ? 1U : 0U,
                   s_device_pairing_bonded ? 1U : 0U,
                   (reason != NULL) ? reason : "unknown");
        switch (state)
        {
        case APP_DEVICE_GATE_WAIT_PAIRING:
            app_task_auto_idle_note_activity("gate_wait_pairing");
            break;
        case APP_DEVICE_GATE_PAIRING_CONFIRM:
            app_task_auto_idle_note_activity("gate_pairing_confirm");
            break;
        case APP_DEVICE_GATE_READY:
            app_task_auto_idle_note_activity("gate_ready");
            break;
        default:
            break;
        }
    }
    s_device_gate_state = state;
}

static bool app_task_device_gate_ready_cached(void)
{
    if (factory_boot_gate_factory_mode_active())
    {
        return false;
    }
    if (factory_boot_gate_locked_user_mode_active())
    {
        return s_device_gate_loaded &&
               s_device_pairing_bonded &&
               ((s_device_gate_state == APP_DEVICE_GATE_READY) ||
                (s_device_gate_state == APP_DEVICE_GATE_PAIRING_SUCCESS_HOLD));
    }

    return s_device_gate_loaded &&
           s_device_first_power_seen &&
           s_device_pairing_bonded &&
           ((s_device_gate_state == APP_DEVICE_GATE_READY) ||
            (s_device_gate_state == APP_DEVICE_GATE_PAIRING_SUCCESS_HOLD));
}

