static bool app_task_timeout_action_channel_ready(uint8_t conn_id)
{
    app_ble_ota_link_snapshot_t link;
    app_ble_ota_link_snapshot(conn_id, &link);
    return link.connected && link.paired && link.encrypted &&
           zy100_ble_ctrl_service_ack_notify_enabled(conn_id);
}

static bool app_task_timeout_action_ready(uint8_t reason, uint32_t now_ms)
{
    if (app_task_shutdown_blocks_new_business() ||
        app_battery_policy_is_critical_locked() ||
        (zy100_offline_v2_storage_state() == ZY100_OFFLINE_V2_STORAGE_ERROR))
    {
        app_task_timeout_action_clear();
        return false;
    }
    if (!app_task_timeout_action_pending())
    {
        s_timeout_action.started_ms = now_ms;
        s_timeout_action.generation = app_ble_connection_bootstrap_generation();
        if (++s_timeout_action_token == 0U) ++s_timeout_action_token;
        s_timeout_action.token = s_timeout_action_token;
        s_timeout_action.conn_id = app_ble_power_conn_id();
        s_timeout_action.reason = reason;
        s_timeout_action.sent = false;
        s_timeout_action.ready =
            !app_task_timeout_action_channel_ready(s_timeout_action.conn_id);
    }
    if (s_timeout_action.reason != reason) return false;
    if (!s_timeout_action.ready &&
        (!app_ble_power_conn_valid(s_timeout_action.conn_id) ||
         (s_timeout_action.generation != app_ble_connection_bootstrap_generation()) ||
         !app_task_timeout_action_channel_ready(s_timeout_action.conn_id) ||
         ((uint32_t)(now_ms - s_timeout_action.started_ms) >=
          ZY100_BLE_TIMEOUT_ACTION_ACK_WAIT_MS)))
        s_timeout_action.ready = true;
    if (!s_timeout_action.ready && !s_timeout_action.sent)
        s_timeout_action.sent = zy100_ble_ctrl_service_notify_timeout_action(
            s_timeout_action.conn_id, app_task_ble_ctrl_device_state(),
            s_timeout_action.generation, s_timeout_action.token, reason);
    return s_timeout_action.ready;
}

static uint32_t app_task_timeout_action_wait_ms(uint32_t wait_ms, uint32_t now_ms)
{
    uint32_t elapsed;
    uint32_t remaining;
    if (!app_task_timeout_action_pending()) return wait_ms;
    elapsed = (uint32_t)(now_ms - s_timeout_action.started_ms);
    if (s_timeout_action.ready || (elapsed >= ZY100_BLE_TIMEOUT_ACTION_ACK_WAIT_MS))
        return 1U;
    remaining = ZY100_BLE_TIMEOUT_ACTION_ACK_WAIT_MS - elapsed;
    /* Retry a busy notify queue using the existing task wait, without a timer. */
    if (!s_timeout_action.sent && (remaining > 100U)) remaining = 100U;
    return (wait_ms < remaining) ? wait_ms : remaining;
}
#endif

bool app_task_timeout_action_ack(uint8_t conn_id, uint8_t seq,
    uint32_t generation, uint32_t token, uint64_t reason)
{
#if ZY100_BUILD_PRODUCTION && ZY100_OFFLINE_FEATURE_V2_ENABLE
    if (!app_task_timeout_action_pending() || !s_timeout_action.sent ||
        s_timeout_action.ready || app_task_shutdown_blocks_new_business() ||
        app_battery_policy_is_critical_locked() ||
        (zy100_offline_v2_storage_state() == ZY100_OFFLINE_V2_STORAGE_ERROR) ||
        !app_task_timeout_action_channel_ready(conn_id) ||
        (s_timeout_action.conn_id != conn_id) ||
        (generation != s_timeout_action.generation) ||
        (generation != app_ble_connection_bootstrap_generation()) ||
        (token != s_timeout_action.token) || (seq != (uint8_t)token) ||
        (reason != (uint64_t)s_timeout_action.reason) ||
        ((uint32_t)((uint32_t)zy100_os_time_ms() - s_timeout_action.started_ms) >=
         ZY100_BLE_TIMEOUT_ACTION_ACK_WAIT_MS)) return false;
    s_timeout_action.ready = true;
    return true;
#else
    (void)conn_id; (void)seq; (void)generation; (void)token; (void)reason;
    return false;
#endif
}

