static bool app_task_device_gate_load_from_store(const char *reason,
                                                 bool force_reload)
{
    zy100_system_info_t info;
    app_device_gate_state_t prev_state = s_device_gate_state;

    if (s_device_gate_loaded && !force_reload)
    {
        return true;
    }

#if ZY100_BUILD_FACTORY
    if (factory_boot_gate_locked_user_mode_active())
    {
        s_device_gate_loaded = true;
        s_device_first_power_seen = true;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_FACTORY_LOCKED_WAIT,
                                  "factory_locked_wait");
        DBG_DIRECT("[DEVICE_GATE] factory locked wait reason=%s",
                   factory_boot_gate_reason());
        return true;
    }
#else
    if (zy100_production_shipping_boot_blocked())
    {
        s_device_gate_loaded = true;
        s_device_first_power_seen = false;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_PRODUCTION_BLOCKED,
                                  "production_shipping_boot_blocked");
        ZY100_LOG_ERROR("[DEVICE_GATE][ERR] production shipping boot blocked");
        return true;
    }
    if (factory_boot_gate_production_blocked())
    {
        s_device_gate_loaded = true;
        s_device_first_power_seen = false;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_PRODUCTION_BLOCKED,
                                  factory_boot_gate_reason());
        ZY100_LOG_ERROR("[DEVICE_GATE][ERR] production blocked reason=%s",
                   factory_boot_gate_reason());
        return true;
    }
    if (zy100_whole_unit_test_active())
    {
        s_device_gate_loaded = true;
        s_device_first_power_seen = true;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_WHOLE_UNIT_TEST,
                                  "whole_unit_active");
        DBG_DIRECT("[DEVICE_GATE] whole_unit pairing=disabled business=blocked");
        return true;
    }
    if (zy100_production_acceptance_active())
    {
        s_device_gate_loaded = true;
        s_device_first_power_seen = true;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_PRODUCTION_ACCEPTANCE,
                                  "factory_ota_acceptance");
        DBG_DIRECT("[DEVICE_GATE] production acceptance pairing=disabled business=blocked");
        return true;
    }
#endif

    memset(&info, 0, sizeof(info));
    if (!zy100_system_info_load(&info))
    {
        s_device_gate_loaded = false;
        s_device_first_power_seen = false;
        s_device_pairing_bonded = false;
        app_task_device_gate_reset_transient();
        app_task_device_set_state(APP_DEVICE_GATE_ERROR, "system_info_load");
        DBG_DIRECT("[DEVICE_GATE] load_failed reason=%s",
                   (reason != NULL) ? reason : "unknown");
        return false;
    }

    if (s_device_gate_loaded && force_reload)
    {
        DBG_DIRECT("[DEVICE_GATE] reload old_state=%s reason=%s",
                   app_task_device_gate_state_name(s_device_gate_state),
                   (reason != NULL) ? reason : "unknown");
    }

    s_device_gate_loaded = true;
    s_device_pairing_bonded = ((info.pairing_bonded != 0U) ||
                               (info.paired_peer_count != 0U));
    app_task_device_gate_reset_transient();

    if (factory_boot_gate_factory_mode_active())
    {
        s_device_first_power_seen = false;
        s_device_pairing_bonded = false;
        s_factory_le_bond_clear_done = false;
        factory_mfg_session_begin();
        if (factory_boot_gate_locked_record_invalid())
        {
            app_task_device_set_state(APP_DEVICE_GATE_FACTORY_WAIT_KEY,
                                      "locked_invalid_recovery");
            DBG_DIRECT("[DEVICE_GATE] locked_invalid_recovery reason=%s",
                       (reason != NULL) ? reason : "unknown");
            return true;
        }
        app_task_device_set_state(APP_DEVICE_GATE_FACTORY_LED_SHOWCASE,
                                  reason);
        DBG_DIRECT("[DEVICE_GATE] factory load old_first_power_seen=%u reason=%s",
                   info.first_power_seen ? 1U : 0U,
                   (reason != NULL) ? reason : "unknown");
        return true;
    }

    if (!zy100_system_info_ensure_current_software_version())
    {
        DBG_DIRECT("[DEVICE_GATE][WARN] version_ensure_failed reason=%s",
                   (reason != NULL) ? reason : "unknown");
    }

    if (factory_boot_gate_locked_user_mode_active())
    {
        s_device_first_power_seen = true;
        if (!s_device_pairing_bonded)
        {
            app_task_device_set_state(APP_DEVICE_GATE_WAIT_PAIRING, reason);
        }
        else
        {
            app_task_device_set_state(APP_DEVICE_GATE_READY, reason);
        }
        if ((prev_state == APP_DEVICE_GATE_PAIRING_SUCCESS_HOLD) &&
            (s_device_gate_state == APP_DEVICE_GATE_READY))
        {
            app_task_device_gate_clear_pairing_hold_visual(reason);
        }
        DBG_DIRECT("[DEVICE_GATE] locked_user load pairing_bonded=%u state=%s reason=%s",
                   s_device_pairing_bonded ? 1U : 0U,
                   app_task_device_gate_state_name(s_device_gate_state),
                   (reason != NULL) ? reason : "unknown");
        return true;
    }

    s_device_first_power_seen = (info.first_power_seen != 0U);
    if (!s_device_first_power_seen)
    {
#if APP_TASK_YHM2712_FIRST_POWER_INIT_ACTIVE
        app_task_device_set_state(APP_DEVICE_GATE_FIRST_YHM_INIT, reason);
#else
        app_task_device_set_state(APP_DEVICE_GATE_FIRST_META_CLEAR, reason);
#endif
    }
    else if (!s_device_pairing_bonded)
    {
        app_task_device_set_state(APP_DEVICE_GATE_WAIT_PAIRING, reason);
    }
    else
    {
        app_task_device_set_state(APP_DEVICE_GATE_READY, reason);
    }
    if ((prev_state == APP_DEVICE_GATE_PAIRING_SUCCESS_HOLD) &&
        (s_device_gate_state == APP_DEVICE_GATE_READY))
    {
        app_task_device_gate_clear_pairing_hold_visual(reason);
    }

    DBG_DIRECT("[DEVICE_GATE] load first_power_seen=%u pairing_bonded=%u state=%s reason=%s",
               s_device_first_power_seen ? 1U : 0U,
               s_device_pairing_bonded ? 1U : 0U,
               app_task_device_gate_state_name(s_device_gate_state),
               (reason != NULL) ? reason : "unknown");
    return true;
}

static bool app_task_device_gate_begin_runtime(const char *reason)
{
    const bool reload_from_store = !s_app_runtime_active ||
                                   !s_device_gate_loaded ||
                                   (s_device_gate_state == APP_DEVICE_GATE_ERROR);

    if (!app_task_device_gate_load_from_store(reason, reload_from_store))
    {
        return false;
    }

    return true;
}

static bool app_task_device_gate_active(void)
{
    if (!s_device_gate_loaded)
    {
        return false;
    }
    return !app_task_device_gate_ready_cached();
}

static bool app_task_device_flash_led_all_rgb(uint8_t red,
                                              uint8_t green,
                                              uint8_t blue)
{
    zy100_rgb_color_t frame[ZY100_RGB_LED_COUNT];
    uint16_t idx;

    for (idx = 0U; idx < ZY100_RGB_LED_COUNT; idx++)
    {
        frame[idx].red = red;
        frame[idx].green = green;
        frame[idx].blue = blue;
    }

    return app_led_request_frame(LED_OWNER_BOOT_SEQUENCE,
                                 LED_PRIORITY_BOOT_SEQUENCE,
                                 frame,
                                 ZY100_RGB_LED_COUNT);
}



