static void app_task_shutdown_led_prepare(const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "shutdown";

    app_task_ble_link_led_cancel(use_reason);
    app_task_charge_led_cancel(use_reason);
    s_device_pairing_blink_last_ms = 0ULL;
    s_device_pairing_success_start_ms = 0ULL;
    s_device_pairing_ble_retry_last_ms = 0ULL;
    app_task_v1_export_wait_blink_stop();
    app_task_ble_clear_red_blink_stop();
    app_ble_export_ui_cancel(use_reason);
    led_release(LED_OWNER_MAG_CALIBRATION);
    led_release(LED_OWNER_BOOT_SEQUENCE);
    /* Reset confirmation reuses shutdown drain, but owns its indication now.
     * Do not render shutdown white before the next reset poll replaces it. */
    if (app_user_reset_needs_drain())
    {
        app_user_reset_port_led(USER_RESET_DRAIN, 0U);
    }
    else
    {
        (void)app_led_request_logo(LED_OWNER_BUTTON_HOLD,
                                   LED_PRIORITY_BUTTON_HOLD,
                                   LED_PATTERN_LOGO_WHITE_HINT);
    }
}

