#if F_APP_DLPS_SPI_PROBE_ENABLE
static bool app_dlps_spi_probe_wait_flag(uint8_t flag, FlagStatus target)
{
    uint32_t guard = APP_DLPS_SPI_PROBE_TIMEOUT_LOOP;

    while (SPI_GetFlagState(SPI0, flag) != target)
    {
        if (guard-- == 0U)
        {
            return false;
        }
    }
    return true;
}

static void app_dlps_spi_probe_flush_rx(void)
{
    while (SPI_GetFlagState(SPI0, SPI_FLAG_RFNE) == SET)
    {
        (void)SPI_ReceiveData(SPI0);
    }
}

static uint8_t app_dlps_spi_probe_sw_cs_level(void)
{
    if (s_app_dlps_spi_probe_sw_cs_mask == 0U)
    {
        return 0U;
    }

    return GPIO_ReadOutputDataBit(s_app_dlps_spi_probe_sw_cs_mask);
}

static void app_dlps_spi_probe_set_sw_cs(bool high_level, const char *tag)
{
    if (s_app_dlps_spi_probe_sw_cs_mask == 0U)
    {
        DBG_DIRECT("[APP_SPI_PROBE][WARN] SW CS mask is 0, skip set");
        return;
    }

    if (high_level)
    {
        GPIO_SetBits(s_app_dlps_spi_probe_sw_cs_mask);
    }
    else
    {
        GPIO_ResetBits(s_app_dlps_spi_probe_sw_cs_mask);
    }

    DBG_DIRECT("[APP_SPI_PROBE] %s SW_CS(pin=%d)=%d",
               (tag != NULL) ? tag : "set",
               APP_DLPS_SPI_PROBE_SW_CS_PIN,
               app_dlps_spi_probe_sw_cs_level());
}

static void app_dlps_spi_probe_init(void)
{
    GPIO_InitTypeDef gpio_init;
    SPI_InitTypeDef spi_init;

    RCC_PeriphClockCmd(APBPeriph_SPI0, APBPeriph_SPI0_CLOCK, ENABLE);
    RCC_PeriphClockCmd(APBPeriph_GPIO, APBPeriph_GPIO_CLOCK, ENABLE);

    Pad_Config(P4_0, PAD_PINMUX_MODE, PAD_IS_PWRON, PAD_PULL_UP, PAD_OUT_ENABLE, PAD_OUT_HIGH);
    Pad_Config(P4_2, PAD_PINMUX_MODE, PAD_IS_PWRON, PAD_PULL_UP, PAD_OUT_ENABLE, PAD_OUT_HIGH);
    Pad_Config(P4_1, PAD_PINMUX_MODE, PAD_IS_PWRON, PAD_PULL_UP, PAD_OUT_ENABLE, PAD_OUT_HIGH);
    Pad_Config(APP_DLPS_SPI_PROBE_SW_CS_PIN, PAD_PINMUX_MODE, PAD_IS_PWRON, PAD_PULL_UP,
               PAD_OUT_ENABLE, PAD_OUT_HIGH);

    Pinmux_Deinit(P4_0);
    Pinmux_Deinit(P4_1);
    Pinmux_Deinit(P4_2);
    Pinmux_Deinit(APP_DLPS_SPI_PROBE_SW_CS_PIN);
    Pinmux_Config(P4_0, SPI0_CLK_MASTER);
    Pinmux_Config(P4_2, SPI0_MO_MASTER);
    Pinmux_Config(P4_1, SPI0_MI_MASTER);
    Pinmux_Config(APP_DLPS_SPI_PROBE_SW_CS_PIN, DWGPIO);

    GPIO_StructInit(&gpio_init);
    s_app_dlps_spi_probe_sw_cs_mask = GPIO_GetPin(APP_DLPS_SPI_PROBE_SW_CS_PIN);
    gpio_init.GPIO_Pin = s_app_dlps_spi_probe_sw_cs_mask;
    gpio_init.GPIO_Mode = GPIO_Mode_OUT;
    gpio_init.GPIO_ControlMode = GPIO_SOFTWARE_MODE;
    gpio_init.GPIO_ITCmd = DISABLE;
    GPIO_Init(&gpio_init);
    app_dlps_spi_probe_set_sw_cs(true, "init");

    SPI_StructInit(&spi_init);
    spi_init.SPI_Direction = SPI_Direction_FullDuplex;
    spi_init.SPI_Mode = SPI_Mode_Master;
    spi_init.SPI_DataSize = SPI_DataSize_8b;
    spi_init.SPI_CPOL = SPI_CPOL_Low;
    spi_init.SPI_CPHA = SPI_CPHA_1Edge;
    spi_init.SPI_BaudRatePrescaler = SPI_BaudRatePrescaler_8;
    spi_init.SPI_RxThresholdLevel = 1U;
    spi_init.SPI_NDF = 0U;
    spi_init.SPI_FrameFormat = SPI_Frame_Motorola;
    SPI_Init(SPI0, &spi_init);
    SPI_Cmd(SPI0, ENABLE);
    ZY100_DIAG_LOG("[APP_SPI_PROBE] init done: use SW CS(pin=%d) + IMU mode0",
               APP_DLPS_SPI_PROBE_SW_CS_PIN);
}

static bool app_dlps_spi_probe_send_byte(uint8_t data)
{
    if (!app_dlps_spi_probe_wait_flag(SPI_FLAG_TFNF, SET))
    {
        return false;
    }

    SPI_SendData(SPI0, data);
    return true;
}

static bool app_dlps_spi_probe_transfer_collect(const uint8_t *tx_buf, uint8_t *rx_buf, uint8_t len)
{
    uint8_t i;
    uint32_t guard;

    if ((tx_buf == NULL) || (rx_buf == NULL) || (len == 0U))
    {
        return false;
    }

    app_dlps_spi_probe_flush_rx();
    for (i = 0U; i < len; i++)
    {
        if (!app_dlps_spi_probe_send_byte(tx_buf[i]))
        {
            return false;
        }
    }

    if (!app_dlps_spi_probe_wait_flag(SPI_FLAG_BUSY, RESET))
    {
        return false;
    }

    guard = APP_DLPS_SPI_PROBE_TIMEOUT_LOOP;
    while (SPI_GetRxFIFOLen(SPI0) < len)
    {
        if (guard-- == 0U)
        {
            return false;
        }
    }

    for (i = 0U; i < len; i++)
    {
        rx_buf[i] = (uint8_t)SPI_ReceiveData(SPI0);
    }

    app_dlps_spi_probe_flush_rx();
    return true;
}

static bool app_dlps_spi_probe_read_imu_whoami(uint8_t *whoami_std, uint8_t *whoami_extra_dummy)
{
    uint8_t tx_std[2] = {APP_DLPS_SPI_PROBE_IMU_WHOAMI_CMD, APP_DLPS_SPI_PROBE_DUMMY_TX};
    uint8_t rx_std[2] = {0};
    uint8_t tx_ext[3] = {APP_DLPS_SPI_PROBE_IMU_WHOAMI_CMD, APP_DLPS_SPI_PROBE_DUMMY_TX,
                         APP_DLPS_SPI_PROBE_DUMMY_TX};
    uint8_t rx_ext[3] = {0};

    if ((whoami_std == NULL) || (whoami_extra_dummy == NULL))
    {
        return false;
    }

    ZY100_DIAG_LOG("[APP_SPI_PROBE] tx begin on SW CS(pin=%d), WHO_AM_I cmd=0x%02x",
               APP_DLPS_SPI_PROBE_SW_CS_PIN, APP_DLPS_SPI_PROBE_IMU_WHOAMI_CMD);
    app_dlps_spi_probe_set_sw_cs(false, "tx-begin");

    if (!app_dlps_spi_probe_transfer_collect(tx_std, rx_std, (uint8_t)sizeof(tx_std)))
    {
        app_dlps_spi_probe_set_sw_cs(true, "tx-abort");
        return false;
    }

    if (!app_dlps_spi_probe_transfer_collect(tx_ext, rx_ext, (uint8_t)sizeof(tx_ext)))
    {
        app_dlps_spi_probe_set_sw_cs(true, "tx-abort");
        return false;
    }

    app_dlps_spi_probe_set_sw_cs(true, "tx-end");
    *whoami_std = rx_std[1];
    *whoami_extra_dummy = rx_ext[2];
    ZY100_DIAG_LOG("[APP_SPI_PROBE] tx end on SW CS(pin=%d)", APP_DLPS_SPI_PROBE_SW_CS_PIN);
    return true;
}

static void app_task_run_dlps_spi_probe(uint32_t runtime_ms)
{
    uint8_t whoami_std = 0U;
    uint8_t whoami_extra_dummy = 0U;

    if (s_app_dlps_spi_probe_inited)
    {
        if ((runtime_ms - s_app_dlps_spi_probe_last_ms) < (uint32_t)F_APP_DLPS_SPI_PROBE_PERIOD_MS)
        {
            return;
        }
    }

    app_dlps_spi_probe_init();
    s_app_dlps_spi_probe_inited = true;
    s_app_dlps_spi_probe_last_ms = runtime_ms;

    if (app_dlps_spi_probe_read_imu_whoami(&whoami_std, &whoami_extra_dummy))
    {
        ZY100_DIAG_LOG("[APP_SPI_PROBE] IMU WHO_AM_I std=0x%02x extra_dummy=0x%02x expect=0x%02x",
                   whoami_std, whoami_extra_dummy, ICM53611_WHO_AM_I_VALUE);
        if (whoami_std == ICM53611_WHO_AM_I_VALUE)
        {
            ZY100_DIAG_LOG("[APP_SPI_PROBE] IMU WHO_AM_I matched on standard dummy");
        }
        else if (whoami_extra_dummy == ICM53611_WHO_AM_I_VALUE)
        {
            DBG_DIRECT("[APP_SPI_PROBE][WARN] IMU WHO_AM_I appears on second dummy");
        }
        else
        {
            DBG_DIRECT("[APP_SPI_PROBE][WARN] IMU WHO_AM_I mismatch");
        }
    }
    else
    {
        DBG_DIRECT("[APP_SPI_PROBE][WARN] IMU WHO_AM_I probe failed");
    }
}
#endif

#if F_LP_TEST_PURE_DLPS
static void app_task_run_pure_dlps_test(void)
{
    uint32_t remain_s = APP_DLPS_TEST_COUNTDOWN_S;
    bool packaged_ok;

    while (remain_s > 0U)
    {
        DBG_DIRECT("[LP_TEST] dlps countdown: %d", remain_s);
        os_delay(1000);
        remain_s--;
    }

    DBG_DIRECT("[LP_TEST] dlps countdown: 0");
    DBG_DIRECT("[LP_TEST] enter packaged pure DLPS mode");
    packaged_ok = lp_dlps_enter_packaged_mode();
    if (!packaged_ok)
    {
        DBG_DIRECT("[LP_TEST][ABORT] packaged mode blocked: flash DPD not confirmed");
        DBG_DIRECT("[LP_TEST][ABORT] skip task suspend and keep ACTIVE mode for diagnosis");
        return;
    }

    DBG_DIRECT("[LP_TEST] apply task step-test policy");
    (void)lp_dlps_apply_task_step_test(app_task_handle);
}
#endif


