static void app_task_mag_cal_led_poll(void)
{
    uint8_t visual = zy100_cal_manager_mag_visual_state();
    led_pattern_t pattern;

    if (visual == ZY100_CAL_MAG_VISUAL_ACTIVE)
    {
        if (!led_owner_is_active(LED_OWNER_MAG_CALIBRATION))
        {
            led_pattern_notify_purple_breath(&pattern, false);
            (void)led_request(LED_OWNER_MAG_CALIBRATION,
                              LED_PRIORITY_MAG_CALIBRATION, &pattern);
        }
        return;
    }
    if (visual == ZY100_CAL_MAG_VISUAL_CANCEL)
    {
        led_release(LED_OWNER_MAG_CALIBRATION);
        zy100_cal_manager_mag_visual_result_consumed();
        return;
    }
    if (visual == ZY100_CAL_MAG_VISUAL_SUCCESS)
    {
        led_pattern_notify_blink(&pattern, LED_PATTERN_COLOR_PURPLE,
                                 (uint32_t)APP_BLE_UPLOAD_LED_FAST_ON_MS,
                                 (uint32_t)APP_BLE_UPLOAD_LED_FAST_OFF_MS,
                                 3U, false);
        (void)led_request(LED_OWNER_MAG_CALIBRATION,
                          LED_PRIORITY_MAG_CALIBRATION, &pattern);
        zy100_cal_manager_mag_visual_result_consumed();
        return;
    }
    if (visual == ZY100_CAL_MAG_VISUAL_FAILURE)
    {
        led_pattern_notify_blink(&pattern, LED_PATTERN_COLOR_RED,
                                 (uint32_t)APP_BLE_UPLOAD_LED_FAST_ON_MS,
                                 (uint32_t)APP_BLE_UPLOAD_LED_FAST_OFF_MS,
                                 3U, false);
        (void)led_request(LED_OWNER_MAG_CALIBRATION,
                          LED_PRIORITY_MAG_CALIBRATION, &pattern);
        zy100_cal_manager_mag_visual_result_consumed();
    }
}

static void app_task_calibration_runtime_poll(void)
{
    bool active_before = zy100_cal_manager_mag_active();
    bool active_after;

    app_ble_calibration_poll();
    active_after = zy100_cal_manager_mag_active();
    if (active_after)
    {
        s_mag_cal_runtime_seen_active = true;
    }
    else if (active_before || s_mag_cal_runtime_seen_active)
    {
        s_mag_cal_runtime_seen_active = false;
        app_task_auto_idle_note_calibration_exit();
    }
}

