static void app_task_imu_wom_disarm_wakeup_pin(void)
{
#if (IMU_INT_PIN != IMU_PIN_UNASSIGNED)
    System_WakeUpPinDisable(IMU_INT_PIN);
    Pad_ClearWakeupINTPendingBit(IMU_INT_PIN);
#endif
    NVIC_ClearPendingIRQ(System_IRQn);
}

static bool app_task_imu_wom_rearm_wakeup_pin(void)
{
#if (IMU_INT_PIN != IMU_PIN_UNASSIGNED)
    Pad_Config(IMU_INT_PIN, PAD_SW_MODE, PAD_IS_PWRON, PAD_PULL_NONE,
               PAD_OUT_DISABLE, PAD_OUT_LOW);
    Pad_ClearWakeupINTPendingBit(IMU_INT_PIN);
#if (ZY100_IMU_WOM_WAKE_DEBOUNCE_MS > 0U)
    System_WakeUpDebounceTime((uint8_t)ZY100_IMU_WOM_WAKE_DEBOUNCE_MS);
    System_WakeUpPinEnable(IMU_INT_PIN, PAD_WAKEUP_POL_LOW, PAD_WK_DEBOUNCE_ENABLE);
#else
    System_WakeUpPinEnable(IMU_INT_PIN, PAD_WAKEUP_POL_LOW, PAD_WK_DEBOUNCE_DISABLE);
#endif
    NVIC_ClearPendingIRQ(System_IRQn);
    NVIC_EnableIRQ(System_IRQn);
    return true;
#else
    return false;
#endif
}

#if ZY100_CHARGE_LED_ENABLE
static bool app_task_rearm_charge_wakeup(bool *charge_present_out,
                                         uint8_t *wake_polarity_out)
{
    bool chg_present = false;
    uint8_t chg_wake_polarity = 0U;
    bsp_power_status_t chg_status;

    if (charge_present_out != NULL)
    {
        *charge_present_out = false;
    }
    if (wake_polarity_out != NULL)
    {
        *wake_polarity_out = 0U;
    }

    chg_status = bsp_power_status_chg_int_rearm_wakeup(&chg_present,
                                                        &chg_wake_polarity);
    if (chg_status != BSP_POWER_STATUS_OK)
    {
        DBG_DIRECT("[LP_WAKE_SRC][ERR] chg_int_rearm=%s(%u)",
                   bsp_power_status_name(chg_status),
                   (uint32_t)chg_status);
        return false;
    }

    svc_charge_status_update_external_power_present(chg_present);
    if (charge_present_out != NULL)
    {
        *charge_present_out = chg_present;
    }
    if (wake_polarity_out != NULL)
    {
        *wake_polarity_out = chg_wake_polarity;
    }
    if (!chg_present)
    {
        app_task_charge_logo_chase_reset("chg_int_rearm_absent");
    }

#if ZY100_CHG_WAKE_DIAG_LOG_ENABLE
    DBG_DIRECT("[LP_WAKE_SRC] chg_int_rearm ok=1 present=%u pol=%u",
               chg_present ? 1U : 0U,
               (uint32_t)chg_wake_polarity);
#endif
    return true;
}
#endif

static bool app_task_rearm_dlps_wakeup_sources_with_charge(
    bool *charge_present_out)
{
    bool ok = true;
#if ZY100_CHARGE_LED_ENABLE
    bool chg_present = false;
    uint8_t chg_wake_polarity = 0U;
#endif

    if (charge_present_out != NULL)
    {
        *charge_present_out = false;
    }

    if (s_button_sleep_release_guard_active)
    {
        if (!app_task_button_is_pressed_now())
        {
            app_task_button_clear_release_guard_for_sleep_entry("already_released");
            ok = app_button_dlps_rearm_wakeup();
        }
        else
        {
            ok = app_button_dlps_rearm_release_wakeup();
            if (!app_task_button_is_pressed_now())
            {
                app_task_button_clear_release_guard_for_sleep_entry("released_after_release_rearm");
                Pad_ClearWakeupINTPendingBit(APP_BUTTON_PIN);
                NVIC_ClearPendingIRQ(System_IRQn);
                ok = app_button_dlps_rearm_wakeup();
            }
        }
    }
    else
    {
        ok = app_button_dlps_rearm_wakeup();
    }

    if (s_imu_wom_sleep_armed && !app_task_imu_wom_rearm_wakeup_pin())
    {
        ok = false;
    }

#if ZY100_CHARGE_LED_ENABLE
    if (!app_task_rearm_charge_wakeup(&chg_present, &chg_wake_polarity))
    {
        ok = false;
    }
    else
    {
        if (charge_present_out != NULL)
        {
            *charge_present_out = chg_present;
        }
    }
    ZY100_LOG_VERBOSE("[LP_WAKE_SRC] rearm ok=%u guard=%u button_pressed=%u imu_armed=%u chg_present=%u chg_pol=%u",
                      ok ? 1U : 0U,
                      s_button_sleep_release_guard_active ? 1U : 0U,
                      app_task_button_is_pressed_now() ? 1U : 0U,
                      s_imu_wom_sleep_armed ? 1U : 0U,
                      chg_present ? 1U : 0U,
                      (uint32_t)chg_wake_polarity);
#else
    ZY100_LOG_VERBOSE("[LP_WAKE_SRC] rearm ok=%u guard=%u button_pressed=%u imu_armed=%u",
                      ok ? 1U : 0U,
                      s_button_sleep_release_guard_active ? 1U : 0U,
                      app_task_button_is_pressed_now() ? 1U : 0U,
                      s_imu_wom_sleep_armed ? 1U : 0U);
#endif

    return ok;
}

