static void app_task_button_hold_confirm_shutdown_release(uint64_t runtime_ms);

static const char *app_power_state_name(app_power_state_t state)
{
    switch (state)
    {
    case APP_POWER_STATE_ACTIVE:
        return "ACTIVE";
    case APP_POWER_STATE_STANDBY_FULL:
        return "STANDBY_FULL";
    case APP_POWER_STATE_STANDBY_CHARGE:
        return "STANDBY_CHARGE";
    case APP_POWER_STATE_FULL_SLEEP_DLPS:
        return "FULL_SLEEP_DLPS";
    case APP_POWER_STATE_CHARGE_PARTIAL_SLEEP:
        return "CHARGE_PARTIAL_SLEEP";
    default:
        return "UNKNOWN";
    }
}

/* The app owns the SENSOR-PWR transition; mag_capture_service owns the
 * MMC5603 operating mode.  Call this only after the caller has completed its
 * existing rail-settle and board/bus restore sequence. */
static bool app_task_mag_park_after_sensor_restore(const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "sensor_restore";
    mag_status_t mag_status;

    /* A retained rail may still host an online/calibration owner.  Only a
     * new physical rail epoch needs the mandatory notify-on + Power Down
     * sequence; never park a known-retained rail from a generic wake helper. */
    if (s_app_sensor_rail_known_on && !s_app_sensor_rail_park_required)
    {
        return true;
    }

    if (!s_app_sensor_rail_known_on)
    {
        mag_status = mag_capture_service_notify_sensor_rail_on();
        if (mag_status != MAG_STATUS_OK)
        {
            ZY100_LOG_ERROR("[MAG_RAIL][ERR] notify_on rs=%s st=%u",
                       use_reason,
                       (uint32_t)mag_status);
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
            if (s_wom_cycle.active) (void)app_task_wom_fail(APP_WOM_FAULT_MAG, s_wom_cycle.step, (uint8_t)mag_status);
#endif
            return false;
        }
        s_app_sensor_rail_known_on = true;
        s_app_sensor_rail_park_required = true;
    }

    if (mag_capture_service_is_parked())
    {
        s_app_sensor_rail_park_required = false;
        return true;
    }

    mag_status = mag_capture_service_park();
    if (mag_status != MAG_STATUS_OK)
    {
        ZY100_LOG_ERROR("[MAG_RAIL][ERR] park rs=%s st=%u",
                   use_reason,
                   (uint32_t)mag_status);
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
        if (s_wom_cycle.active) (void)app_task_wom_fail(APP_WOM_FAULT_MAG, s_wom_cycle.step, (uint8_t)mag_status);
#endif
        return false;
    }

    s_app_sensor_rail_park_required = false;
    DBG_DIRECT("[MAG_RAIL] parked rs=%s", use_reason);
    return true;
}

/* Retained-power sleep keeps SENSOR-PWR high for ADC/WOM use, but MMC5603
 * must already be in Power Down before the I2C pads are parked for DLPS. */
static app_mag_park_result_t app_task_mag_park_for_retained_sleep_result(uint32_t *status)
{
    mag_status_t mag_status;
    imu_status_t imu_status;
    uint8_t power_out = 0U, power_in = 0U;
    *status = 0U;
    if (!s_app_sensor_rail_known_on)
    {
        imu_status = imu_bsp_get_power_level(&power_out, &power_in);
        *status = (uint32_t)imu_status;
        if (imu_status != IMU_STATUS_OK) return APP_MAG_PARK_POWER_QUERY;
        if (power_out == 0U && power_in == 0U) return APP_MAG_PARK_OK;
        if (!s_imu_wom_sensor_vdd_settled) return APP_MAG_PARK_UNSETTLED;
        mag_status = mag_capture_service_notify_sensor_rail_on();
        *status = (uint32_t)mag_status;
        if (mag_status != MAG_STATUS_OK)
            return mag_status == MAG_STATUS_BUS_BUSY ? APP_MAG_PARK_BUSY : APP_MAG_PARK_LIFECYCLE;
        s_app_sensor_rail_known_on = true;
        s_app_sensor_rail_park_required = true;
    }
    mag_status = mag_capture_service_park();
    *status = (uint32_t)mag_status;
    if (mag_status == MAG_STATUS_BUS_BUSY) return APP_MAG_PARK_BUSY;
    if (mag_status != MAG_STATUS_OK)
        return mag_capture_service_lifecycle() == MAG_CAPTURE_LIFECYCLE_RAIL_OFF ?
               APP_MAG_PARK_LIFECYCLE : APP_MAG_PARK_IO;
    s_app_sensor_rail_park_required = false;
    return APP_MAG_PARK_OK;
}

static bool app_task_mag_park_for_retained_sleep(const char *reason)
{
    static uint32_t last_signature;
    static uint32_t last_log_ms;
    uint32_t status;
    app_mag_park_result_t result = app_task_mag_park_for_retained_sleep_result(&status);
    if (result == APP_MAG_PARK_OK)
    {
        last_signature = 0U;
        return true;
    }
    uint32_t signature = ((uint32_t)result << 16) | status;
    uint32_t now = (uint32_t)zy100_os_time_ms();
    if (signature != last_signature || (uint32_t)(now - last_log_ms) >= 1000U)
    {
        ZY100_LOG_ERROR("[MAG_STOP] rs=%s src=%u result=%u st=%u",
            reason != NULL ? reason : "sleep", (unsigned)app_shutdown_transaction_view()->source,
            (unsigned)result, (unsigned)status);
        ZY100_LOG_ERROR("[MAG_STOP] rail=%u known=%u settled=%u life=%u owner=%u users=%u i2c_sleep=%u",
            (unsigned)imu_bsp_power_mode(), s_app_sensor_rail_known_on ? 1U : 0U,
            s_imu_wom_sensor_vdd_settled ? 1U : 0U,
            (unsigned)mag_capture_service_lifecycle(), (unsigned)mag_capture_service_owner(),
            (unsigned)imu_bsp_power_users(), mag_bsp_i2c_is_suspended() ? 1U : 0U);
        last_signature = signature;
        last_log_ms = now;
    }
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
    if (s_wom_cycle.active) (void)app_task_wom_fail(APP_WOM_FAULT_MAG, s_wom_cycle.step, (uint8_t)status);
#endif
    return false;
}

/* Full shutdown and the enabled Standby rail-off policy may remove
 * SENSOR-PWR.  Do not lower the rail until MMC5603 Power Down has completed
 * for this rail epoch. */
static bool app_task_sensor_power_off_for_shutdown(const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "shutdown";
    imu_status_t imu_status;

    if (!app_task_mag_park_for_retained_sleep(use_reason))
    {
        return false;
    }

    lp_dlps_set_sensor_power_hold(false);
    imu_status = imu_bsp_power_ctrl(false);
    if (imu_status != IMU_STATUS_OK)
    {
        /* Keep the DLPS policy from subsequently pulling a rail whose state
         * the app could not establish. */
        lp_dlps_set_sensor_power_hold(true);
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
        if (s_wom_cycle.active) (void)app_task_wom_fail(APP_WOM_FAULT_POWER, 4U, (uint8_t)imu_status);
#endif
        DBG_DIRECT("[MAG_RAIL][ERR] power_off rs=%s st=%u",
                   use_reason,
                   (uint32_t)imu_status);
        return false;
    }

    mag_capture_service_notify_sensor_rail_off();
    s_app_sensor_rail_known_on = false;
    s_app_sensor_rail_park_required = false;
    s_imu_wom_sensor_vdd_settled = false;
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
    gd25q32e_notify_power_lost();
    s_wom_flash_verify_required = true;
    imu_bsp_mark_lost_after_dlps_prepare();
#endif
    DBG_DIRECT("[MAG_RAIL] rail_off rs=%s", use_reason);
    return true;
}

static void app_power_keep_active_for_factory(const char *reason)
{
    const char *use_reason = (reason != NULL) ? reason : "factory";

    if (!factory_boot_gate_factory_mode_active())
    {
        return;
    }

    lps_mode_set(LPM_ACTIVE_MODE);
    app_power_manager_report(APP_POWER_FACTORY_ACTIVE);
    s_button_dlps_state = APP_BUTTON_DLPS_STATE_ACTIVE;
    s_app_sleep_pending = false;
    s_app_sensor_stop_requested_for_sleep = false;
    s_button_sleep_request_pending = false;
    app_button_clear_wake_irq();
    s_imu_wom_wakeup_irq_pending = false;
#if ZY100_CHARGE_LED_ENABLE
    s_charge_wakeup_irq_pending = false;
#endif
    s_app_v0_sleep_allowed = false;
    lp_dlps_set_sensor_power_hold(true);
    if (!s_app_runtime_active)
    {
        s_app_runtime_start_req = true;
    }

    svc_app_watchdog_enable_active(use_reason);
    DBG_DIRECT("[APP_POWER] factory_keep_active reason=%s runtime_active=%u runtime_req=%u",
               use_reason,
               s_app_runtime_active ? 1U : 0U,
               s_app_runtime_start_req ? 1U : 0U);
}

static void app_power_request_active_runtime_recovery_ex(const char *reason, bool preserve_input)
{
    const char *use_reason = (reason != NULL) ? reason : "active_recover";

    if (app_power_manager_request(APP_POWER_REQUEST_RECOVERY) == APP_POWER_BUSY)
    {
        s_app_sleep_pending = true;
        app_task_shutdown_note_retry(use_reason);
        DBG_DIRECT("[SHUTDOWN] active_recovery_blocked reason=%s", use_reason);
        return;
    }

    lps_mode_set(LPM_ACTIVE_MODE);
    app_power_manager_report(APP_POWER_RECOVERY_ACTIVE);
    s_button_dlps_state = APP_BUTTON_DLPS_STATE_ACTIVE;
    s_app_v0_sleep_allowed = false;
    lp_dlps_set_sensor_power_hold(true);
    if (!preserve_input)
    {
        app_button_clear_wake_irq();
        s_imu_wom_wakeup_irq_pending = false;
#if ZY100_CHARGE_LED_ENABLE
        s_charge_wakeup_irq_pending = false;
#endif
    }
    s_app_sleep_pending = false;
    s_app_sensor_stop_requested_for_sleep = false;
    if (!s_app_runtime_active)
    {
        s_app_runtime_start_req = true;
    }

    svc_app_watchdog_enable_active(use_reason);
    DBG_DIRECT("[APP_RECOVER] active_runtime_request reason=%s runtime_active=%u runtime_req=%u",
               use_reason,
               s_app_runtime_active ? 1U : 0U,
               s_app_runtime_start_req ? 1U : 0U);
}

static void app_power_request_active_runtime_recovery(const char *reason)
{
    app_power_request_active_runtime_recovery_ex(reason, false);
}

