static void app_task_button_preview_tier(app_button_tier_t tier,
                                         uint64_t hold_ms)
{
    if (app_power_state_is_standby(app_power_manager_mode()))
    {
        zy100_power_reset_trace_set_phase(ZY100_POWER_TRACE_BUTTON_TIER,
                                          (uint8_t)app_power_manager_mode());
        DBG_DIRECT("[BTN_HOLD] tier=%s hold_ms=%llu standby_no_led=1",
                   app_task_button_tier_name(tier),
                   (unsigned long long)hold_ms);
        return;
    }

    switch (tier)
    {
    case APP_BUTTON_TIER_SHUTDOWN:
        (void)app_led_request_logo(LED_OWNER_BUTTON_HOLD,
                                   LED_PRIORITY_BUTTON_HOLD,
                                   LED_PATTERN_LOGO_WHITE_HINT);
        break;
    case APP_BUTTON_TIER_PAIRING_HINT:
        /* Blue means advertising is confirmed, not merely five seconds elapsed. */
        break;
    case APP_BUTTON_TIER_FACTORY_HINT:
        (void)app_led_request_notify_blink(LED_OWNER_BUTTON_HOLD,
                                           LED_PRIORITY_BUTTON_HOLD,
                                           LED_PATTERN_COLOR_RED,
                                           800U,
                                           800U,
                                           0U,
                                           false);
        break;
    case APP_BUTTON_TIER_NONE:
    default:
        break;
    }

    DBG_DIRECT("[BTN_HOLD] tier=%s hold_ms=%llu preview=1",
               app_task_button_tier_name(tier),
               (unsigned long long)hold_ms);
}

static bool app_task_ensure_event_queue_for_wake(void)
{
    if (evt_queue_handle != NULL)
    {
        return true;
    }

    if (!os_msg_queue_create(&evt_queue_handle, MAX_NUMBER_OF_EVENT_MESSAGE, sizeof(uint8_t)))
    {
        ZY100_LOG_ERROR("[APP_TASK][ERR] wake event queue create failed");
        return false;
    }

    return true;
}

static bool app_task_prepare_boot_dlps(void)
{
    s_app_runtime_active = false;
    s_app_runtime_start_req = false;
    s_app_sleep_pending = false;
    s_button_sleep_request_pending = false;
    s_button_sleep_release_guard_active = false;
    app_task_button_shutdown_release_gate_clear();
    app_task_button_training_click_reset();
    app_task_button_hold_reset();
    app_button_clear_wake_irq();
    s_imu_wom_wakeup_irq_pending = false;
#if ZY100_CHARGE_LED_ENABLE
    s_charge_wakeup_irq_pending = false;
#endif
    s_app_sensor_stop_requested_for_sleep = false;
    s_app_v0_sleep_allowed = false;
    s_app_v0_capture_done_logged = false;

    DBG_DIRECT("[V0_PWR] boot done, enter DLPS wait key");
    if (!app_task_ensure_event_queue_for_wake())
    {
        return false;
    }

    return true;
}

