static void app_task_v1_export_wait_blink_begin(void)
{
    app_task_charge_led_cancel("export_wait_blink");
    s_v1_export_wait_blink_enabled = true;
    s_v1_export_wait_blink_on = true;
    s_v1_export_wait_blink_last_ms = os_sys_time_get();
    (void)app_led_request_notify_blink(LED_OWNER_PENDING_EXPORT,
                                       LED_PRIORITY_PENDING_EXPORT,
                                       LED_PATTERN_COLOR_BLUE,
                                       V1_EXPORT_WAIT_BLINK_MS,
                                       V1_EXPORT_WAIT_BLINK_MS,
                                       0U,
                                       false);
    APP_LED_LOG("[LED] blue_blink");
}

