static void app_task_v1_cached_session_clear(void)
{
    s_v1_last_session_valid = false;
    s_v1_export_in_progress = false;
    s_app_v1_export_ready_preserved_for_sleep = false;
    app_task_v1_export_wait_blink_stop();
    memset(&s_app_v1_export_session, 0, sizeof(s_app_v1_export_session));
    zy100_capture_time_reset();
    zy100_training_session_clear_active();
    zy100_training_session_clear_completed();
}

static bool app_task_v1_sleep_preserved_export_ready_valid(void) __attribute__((unused));
static bool app_task_v1_sleep_preserved_export_ready_valid(void)
{
    if (!s_app_v1_export_ready_preserved_for_sleep || !s_v1_last_session_valid)
    {
        return false;
    }

#if ZY100_FINAL_EDGE_MODE_ENABLE
    return imu_fifo_drain_test_final_edge_export_ready();
#else
    return true;
#endif
}

#if !(ZY100_FINAL_EDGE_MODE_ENABLE && ZY100_MULTI_SESSION_STORAGE_ENABLE)
static bool app_task_v1_restore_export_ready_after_button_wake(void)
{
    if (!app_task_v1_sleep_preserved_export_ready_valid())
    {
        s_app_v1_export_ready_preserved_for_sleep = false;
        return false;
    }

    s_app_v1_state = APP_V1_STATE_EXPORT_WAIT_START;
    s_v1_export_in_progress = false;
#if ZY100_FINAL_EDGE_MODE_ENABLE
    v0_final_edge_led_set_export_ready();
#else
    app_task_v1_export_wait_blink_begin();
#endif
    s_app_v1_export_ready_preserved_for_sleep = false;
    DBG_DIRECT("[LP_WAKE] restore_export_ready=1");
    return true;
}
#endif

static void app_task_v1_cache_session(bool recovered)
{
    (void)recovered;
    s_v1_last_session_valid = true;
    s_v1_export_in_progress = false;
#if ZY100_FINAL_EDGE_MODE_ENABLE
#if ZY100_MULTI_SESSION_STORAGE_ENABLE
    app_task_v1_export_wait_blink_stop();
#else
    v0_final_edge_led_set_export_ready();
#endif
#else
    app_task_v1_export_wait_blink_begin();
#endif
#if ZY100_FINAL_EDGE_MODE_ENABLE
    DBG_DIRECT("[FE_EXPORT_READY] state=%u reason=%u",
               (uint32_t)imu_fifo_drain_test_final_edge_capture_state(),
               (uint32_t)imu_fifo_drain_test_final_edge_stop_reason());
#else
    DBG_DIRECT("[EXPORT] wait_start block_count=%u packet_count=%u marker_count=%u",
               s_app_v1_export_session.block_count,
               s_app_v1_export_session.packet_count,
               s_app_v1_export_session.marker_count);
#endif
}

static void app_task_v1_export_wait_blink_tick(uint64_t runtime_ms)
{
    if (!s_v1_export_wait_blink_enabled ||
        !s_v1_last_session_valid ||
        (s_v1_export_in_progress && !app_ble_export_is_active()))
    {
        return;
    }
    if ((s_app_v1_state != APP_V1_STATE_EXPORT_WAIT_START) &&
        (s_app_v1_state != APP_V1_STATE_FAILED_WAIT_RETRY) &&
        !app_ble_export_is_active())
    {
        return;
    }

    if ((runtime_ms - s_v1_export_wait_blink_last_ms) < V1_EXPORT_WAIT_BLINK_MS)
    {
        return;
    }

    s_v1_export_wait_blink_last_ms = runtime_ms;
    s_v1_export_wait_blink_on = !s_v1_export_wait_blink_on;
    led_tick(runtime_ms);
}

