static zy100_capture_time_src_t app_task_capture_time_source(app_capture_req_src_t source)
{
    if (source == APP_CAPTURE_REQ_SRC_BLE)
    {
        return ZY100_CAPTURE_TIME_SRC_BLE;
    }
    if (source == APP_CAPTURE_REQ_SRC_AUTO_MOTION)
    {
        return ZY100_CAPTURE_TIME_SRC_AUTO;
    }
    return ZY100_CAPTURE_TIME_SRC_BUTTON;
}

static void app_task_training_context_log_start(app_capture_req_src_t source,
                                                uint32_t user_id,
                                                uint32_t training_id,
                                                bool synced)
{
    uint64_t rtc_ms = zy100_rtc_clock_now_ms();
    bool calibrated = zy100_rtc_clock_is_calibrated();

    if ((source != APP_CAPTURE_REQ_SRC_BLE) &&
        !synced &&
        !calibrated &&
        (user_id == 1U) &&
        (training_id == 1U))
    {
        DBG_DIRECT("[TRAIN_CTX] start source=%s user=1 train=1 rtc_ms=%llu calibrated=0 source=default",
                   app_task_capture_req_source_name(source),
                   (unsigned long long)rtc_ms);
        return;
    }

    if ((source != APP_CAPTURE_REQ_SRC_BLE) ||
        !app_task_online_quiet_logs_active())
    {
        DBG_DIRECT("[TRAIN_CTX] start source=%s user=%lu train=%lu rtc_ms=%llu calibrated=%u",
                   app_task_capture_req_source_name(source),
                   (unsigned long)user_id,
                   (unsigned long)training_id,
                   (unsigned long long)rtc_ms,
                   calibrated ? 1U : 0U);
    }
}

