bool app_battery_policy_port_capture_stop_in_progress(void)
{
    bool stopping = imu_fifo_drain_test_is_stop_in_progress();
#if ZY100_OFFLINE_FEATURE_V2_ENABLE
    zy100_offline_v2_capture_state_t state =
        zy100_offline_v2_capture_state();

    stopping = stopping ||
        (state == ZY100_OFFLINE_V2_CAPTURE_STOPPING) ||
        (state == ZY100_OFFLINE_V2_CAPTURE_FINALIZING);
#endif
    return stopping;
}

void app_battery_policy_port_request_critical_stop(
    const app_battery_critical_event_t *event)
{
#if ZY100_OFFLINE_FEATURE_V2_ENABLE
    if (zy100_offline_v2_capture_active())
    {
        (void)event;
        zy100_offline_v2_ui_button_stop_cancel();
        (void)zy100_offline_v2_capture_request_stop(
            ZY100_OFFLINE_V2_STOP_LOW_BATTERY);
        s_app_v1_state = APP_V1_STATE_PAUSING_CAPTURE;
        return;
    }
#endif
#if ZY100_ONLINE_STREAM_ENABLE
    if (zy100_online_stream_active() ||
        zy100_online_stream_end_wait_ack())
    {
        uint32_t now_ms = (uint32_t)zy100_os_time_ms();

        app_task_online_low_battery_latch(now_ms, event);
        zy100_online_stream_request_stop(
            ZY100_ONLINE_STOP_REASON_LOW_BATTERY,
            now_ms);
        (void)zy100_online_imu_session_request_low_battery_stop();
        s_app_v1_state = APP_V1_STATE_PAUSING_CAPTURE;
        return;
    }
#else
    (void)event;
#endif
    s_app_v1_state = APP_V1_STATE_PAUSING_CAPTURE;
    imu_fifo_drain_test_request_stop(
        IMU_FIFO_DRAIN_TEST_STOP_REASON_BATTERY_LOW);
}

