bool app_task_calibration_start_ready(void)
{
    uint32_t lock_state;
    bool ble_pending;

    lock_state = os_lock();
    ble_pending = app_task_ble_pending_any_locked();
    os_unlock(lock_state);
    if (!app_task_capture_state_allows_start() ||
        ble_pending || s_app_sleep_pending ||
        s_app_sensor_stop_requested_for_sleep ||
        s_ble_clear_active || s_ble_start_prepare_active ||
        s_training_meta_repair_request ||
        s_training_meta_repair_in_progress)
    {
        return false;
    }
    if (app_task_ota_blocks_new_business())
    {
        return false;
    }
    return true;
}

uint32_t zy100_cal_manager_port_prepare_budget_ms(void)
{
    uint32_t budget = app_ble_ci_state_wait_budget_ms();
    if (budget < ZY100_BLE_CI_STANDBY_EXIT_STUCK_TIMEOUT_MS)
        budget = ZY100_BLE_CI_STANDBY_EXIT_STUCK_TIMEOUT_MS;
    return budget + ZY100_IMU_WOM_SENSOR_PWR_SETTLE_MS +
           BATTERY_ADC_NON_CAPTURE_SETTLE_MS;
}

app_cal_prepare_result_t app_task_calibration_prepare_start(void)
{
    imu_status_t status;
    if (app_task_shutdown_blocks_new_business() ||
        app_task_ota_blocks_new_business()) return APP_CAL_PREPARE_FAILED;
    if (mag_capture_service_owner() != MAG_CAPTURE_OWNER_NONE)
    {
        ZY100_LOG_ERROR("[MAG_CAL][ERR] prepare owner=%u",
                        (uint32_t)mag_capture_service_owner());
        return APP_CAL_PREPARE_FAILED;
    }
    if ((spi_bus_current_owner() != SPI_OWNER_NONE) || battery_adc_is_active())
        return APP_CAL_PREPARE_WAIT;
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
    pwrd_end(PWRD_BUSINESS);
    app_task_active_wom_disarm("calibration_prepare");
#endif
    if (app_power_state_is_standby(app_power_manager_mode()) &&
        !app_power_standby_restore_to_active("ble_calibration_standby", APP_POWER_CAUSE_CALIBRATION))
    {
        ZY100_LOG_ERROR("[MAG_CAL][ERR] prepare standby state=%u", app_power_manager_mode());
        return APP_CAL_PREPARE_FAILED;
    }
    if ((app_power_manager_mode() != APP_POWER_STATE_ACTIVE) || !s_app_runtime_active)
        return APP_CAL_PREPARE_WAIT;
    status = imu_bsp_power_ctrl(true);
    if (status != IMU_STATUS_OK)
    {
        ZY100_LOG_ERROR("[MAG_CAL][ERR] prepare power status=%u", status);
        return APP_CAL_PREPARE_FAILED;
    }
    if (!s_imu_wom_sensor_vdd_settled)
    {
        imu_bsp_delay_us(ZY100_IMU_WOM_SENSOR_PWR_SETTLE_MS * 1000U);
        s_imu_wom_sensor_vdd_settled = true;
    }
    status = imu_bsp_resume_after_dlps();
    if (status != IMU_STATUS_OK)
    {
        ZY100_LOG_ERROR("[MAG_CAL][ERR] prepare bus status=%u", status);
        return APP_CAL_PREPARE_FAILED;
    }
    /* Only this accepted, unowned request may repair an unparked rail epoch. */
    if (!mag_capture_service_is_parked()) s_app_sensor_rail_park_required = true;
    if (!app_task_mag_park_after_sensor_restore("calibration_prepare") ||
        !mag_capture_service_is_parked()) return APP_CAL_PREPARE_FAILED;
    zy100_online_ui_cancel_complete("calibration_start");
#if ZY100_OFFLINE_FEATURE_V2_ENABLE
    zy100_offline_v2_ui_button_stop_cancel();
#endif
    app_task_auto_idle_note_activity("calibration_start");
    return APP_CAL_PREPARE_READY;
}

