bool app_device_pairing_port_prepare_confirm(const char *reason)
{
    if (app_task_shutdown_blocks_new_business())
    {
        return false;
    }
#if F_BT_DLPS_EN && F_APP_BUTTON_DLPS_CTRL_ENABLE
    if (app_power_state_is_standby(app_power_manager_mode()) &&
        !app_power_standby_restore_to_active("ble_connected_standby", APP_POWER_CAUSE_BLE_CONNECTED))
    {
        return false;
    }
#endif
    if (app_task_ble_link_led_active())
    {
        app_task_ble_link_led_cancel("pairing_confirm");
    }
    (void)reason;
    return true;
}

app_ble_ctrl_req_result_t app_task_ble_ctrl_request_online_ready(uint8_t seq,
                                                                 uint8_t conn_id,
                                                                 uint32_t capability_mask,
                                                                 uint64_t host_time_ms)
{
    (void)seq;

    if (app_task_shutdown_blocks_new_business())
    {
        return APP_BLE_CTRL_REQ_RESULT_NOT_READY;
    }

    if (app_task_ota_blocks_new_business())
    {
        return APP_BLE_CTRL_REQ_RESULT_BUSY;
    }

    if (app_ble_offline_v2_sync_blocks_online())
    {
        return APP_BLE_CTRL_REQ_RESULT_BUSY;
    }

    if (!app_ble_power_conn_valid(conn_id) ||
        !zy100_ble_ctrl_service_ack_notify_enabled(conn_id) ||
        !zy100_ble_ctrl_service_export_notify_enabled(conn_id) ||
        ((capability_mask & ZY100_ONLINE_CAPABILITY_REQUIRED_V3) !=
         ZY100_ONLINE_CAPABILITY_REQUIRED_V3))
    {
        DBG_DIRECT("[ONLINE_STATE] ready_reject conn=%u valid=%u ack_ntf=%u export_ntf=%u cap=0x%08lX req=0x%08lX",
                   conn_id,
                   app_ble_power_conn_valid(conn_id) ? 1U : 0U,
                   zy100_ble_ctrl_service_ack_notify_enabled(conn_id) ? 1U : 0U,
                   zy100_ble_ctrl_service_export_notify_enabled(conn_id) ? 1U : 0U,
                   (unsigned long)capability_mask,
                   (unsigned long)ZY100_ONLINE_CAPABILITY_REQUIRED_V3);
        return APP_BLE_CTRL_REQ_RESULT_NOT_READY;
    }
    if (zy100_online_stream_active() ||
        zy100_online_stream_end_wait_ack() ||
        app_task_capture_is_active() ||
        imu_fifo_drain_test_is_busy() ||
        imu_fifo_drain_test_is_start_pending() ||
        imu_fifo_drain_test_is_stop_in_progress())
    {
        return APP_BLE_CTRL_REQ_RESULT_BUSY;
    }
    zy100_online_stream_handle_ready(conn_id,
                                     capability_mask,
                                     host_time_ms,
                                     (uint32_t)zy100_os_time_ms());
    return APP_BLE_CTRL_REQ_RESULT_OK;
}

app_ble_ctrl_req_result_t app_task_ble_ctrl_request_online_record_ack(uint8_t seq,
                                                                      uint8_t conn_id,
                                                                      uint32_t session_id,
                                                                      uint64_t record_id,
                                                                      uint32_t ack_info)
{
    zy100_online_record_type_t type =
        (zy100_online_record_type_t)(ack_info & 0xFFU);
    uint8_t ack_count = (uint8_t)((ack_info >> 8) & 0xFFU);
    uint8_t status = (uint8_t)((ack_info >> 16) & 0xFFU);

    (void)seq;
    zy100_online_stream_handle_record_ack(conn_id,
                                          session_id,
                                          type,
                                          (uint32_t)record_id,
                                          ack_count,
                                          status,
                                          (uint32_t)zy100_os_time_ms());
    return APP_BLE_CTRL_REQ_RESULT_OK;
}

