/**
 * @brief        App task to handle events & messages
 * @param[in]    p_param    Parameters sending to the task
 * @return       void
 */
void app_main_task(void *p_param)
{
#if ZY100_WOM_SENSOR_WEAK_PULL_TEST_ENABLE
    app_task_sensor_access_init();
#endif
#if ZY100_WOM_ACTIVE_STATS_TEST_ENABLE
    if (s_wom_astat_enable_gate != 0U)
    {
        (void)p_param;
        app_task_wom_active_stats_test_main();
        while (true)
        {
            os_delay(1000U);
        }
    }
#endif
#if ZY100_WOM_TIMELINE_TEST_ENABLE
    if (s_wom_tseq_enable_gate != 0U)
    {
        (void)p_param;
        app_task_wom_timeline_test_main();
        while (true)
        {
            os_delay(1000U);
        }
    }
#endif
#if F_LP_TEST_PURE_DLPS
    (void)p_param;
    DBG_DIRECT("[LP_TEST] pure DLPS test task started");
    app_task_run_pure_dlps_test();
    while (true)
    {
        os_delay(1000);
    }
#else
    uint8_t event;
    bool yhm_startup_completed = false;
#if !(F_BT_DLPS_EN && F_APP_BUTTON_DLPS_CTRL_ENABLE)
    bool io_q_ok;
    bool evt_q_ok;
    bool gap_start_ok;
    bool clock_ok;
#endif
    uint64_t runtime_log_last_ms = 0;

#if F_BT_DLPS_EN && F_APP_BUTTON_DLPS_CTRL_ENABLE
    (void)p_param;
#if F_BLE_SKIP_DRIVER_INIT
    DBG_DIRECT("[APP_TASK] driver_init skipped by F_BLE_SKIP_DRIVER_INIT");
#else
    driver_init();
#endif
    svc_app_watchdog_init();
    zy100_online_reset_trace_boot_report();
#if ZY100_CHARGE_LED_ENABLE
    (void)svc_charge_status_init();
#endif
    svc_yhm_startup_begin(&s_yhm_startup, (uint32_t)os_sys_time_get(),
                          0U, app_task_yhm_startup_attempt, NULL);
    svc_app_watchdog_enable_active("yhm_startup");
    app_task_yhm2712_boot_la_toggle_once();

    s_app_runtime_active = false;
    runtime_log_last_ms = os_sys_time_get();
    while (true)
    {
        pwrd_poll();
#if ZY100_OFFLINE_V2_WOM_START_ENABLE
        s_wom_task_epoch++;
#endif
        (void)app_standby_transaction_poll();
        if (app_standby_transaction_pending())
        {
            /* Charger/drain completed, WOM IO still in progress. Service events
             * without starting ACTIVE runtime or replaying the power stages. */
            svc_app_watchdog_poll((uint32_t)zy100_os_time_ms());
            if (evt_queue_handle != NULL && os_msg_recv_intern(evt_queue_handle,
                &event, F_APP_BUTTON_POLL_INTERVAL_MS, "app_main_task", __LINE__))
                app_task_handle_event(event);
            continue;
        }
        if (app_task_yhm_startup_pending(&event)) continue;
        if (!yhm_startup_completed) {
            yhm_startup_completed = true;
#if F_APP_BUTTON_LOG_ENABLE
            if (!app_task_shutdown_blocks_new_business())
                app_task_button_poll_init(os_sys_time_get());
#endif
            app_user_reset_boot();
        }
#if ZY100_OFFLINE_FEATURE_V2_ENABLE
        app_task_offline_start_deadline_poll(zy100_os_time_ms());
#endif
        if (app_power_state_is_standby(app_power_manager_mode()))
        {
            app_task_main_standby_iteration(&event);
            continue;
        }

        if (app_power_manager_mode() == APP_POWER_STATE_CHARGE_PARTIAL_SLEEP)
        {
            app_task_main_charge_partial_sleep_iteration(&event);
            continue;
        }

        if (s_button_dlps_state == APP_BUTTON_DLPS_STATE_SLEEP)
        {
            app_task_main_button_dlps_sleep_iteration(&event);
            continue;
        }

        if (app_task_main_prepare_active_iteration(&runtime_log_last_ms))
        {
            continue;
        }

        {
            uint64_t runtime_ms = zy100_os_time_ms();
            bool b_critical = app_task_final_edge_b_critical_active();

            if (app_task_main_configured_pre_event(runtime_ms, b_critical))
            {
                continue;
            }
            if (app_task_main_event_drain(&event,
                                          &runtime_ms,
                                          &b_critical) &&
                app_task_main_configured_post_event(runtime_ms, b_critical))
            {
                continue;
            }
            app_task_main_configured_loop_tail(runtime_ms,
                                               b_critical,
                                               &runtime_log_last_ms);
        }
        os_delay(1U);
    }

#else
    io_q_ok = os_msg_queue_create(&io_queue_handle, MAX_NUMBER_OF_IO_MESSAGE, sizeof(T_IO_MSG));
    evt_q_ok = os_msg_queue_create(&evt_queue_handle, MAX_NUMBER_OF_EVENT_MESSAGE, sizeof(uint8_t));
    DBG_DIRECT("[APP_TASK] io_q_ok=%d evt_q_ok=%d", io_q_ok, evt_q_ok);
    if (!io_q_ok || !evt_q_ok)
    {
        DBG_DIRECT("[APP_TASK][ERR] message queue create failed");
    }

#if F_APP_BLE_ENABLE
    gap_start_ok = gap_start_bt_stack(evt_queue_handle, io_queue_handle, MAX_NUMBER_OF_GAP_MESSAGE);
    DBG_DIRECT("[APP_TASK] gap_start_bt_stack ok=%d", gap_start_ok);
    if (!gap_start_ok)
    {
        DBG_DIRECT("[APP_TASK][ERR] gap_start_bt_stack reported failure");
    }
#else
    gap_start_ok = true;
    DBG_DIRECT("[APP_TASK] BLE runtime disabled by F_APP_BLE_ENABLE");
#endif
    runtime_log_last_ms = os_sys_time_get();

#if F_BLE_SKIP_DRIVER_INIT
    DBG_DIRECT("[APP_TASK] driver_init skipped by F_BLE_SKIP_DRIVER_INIT");
#else
    driver_init();
#endif
    svc_app_watchdog_init();
    zy100_online_reset_trace_boot_report();
#if ZY100_CHARGE_LED_ENABLE
    (void)svc_charge_status_init();
#endif
    svc_yhm_startup_begin(&s_yhm_startup, (uint32_t)os_sys_time_get(),
                          0U, app_task_yhm_startup_attempt, NULL);
    svc_app_watchdog_enable_active("yhm_startup");
    app_task_yhm2712_boot_la_toggle_once();

    clock_ok = zy100_clock_config_apply_active();
    if (!clock_ok)
    {
        DBG_DIRECT("[CLK_CFG][ERR] active_apply_failed");
    }
    while (true)
    {
        pwrd_poll();
        if (app_task_yhm_startup_pending(&event)) continue;
        if (!yhm_startup_completed) {
            yhm_startup_completed = true;
#if F_APP_BUTTON_LOG_ENABLE
            if (!app_task_shutdown_blocks_new_business())
                app_task_button_poll_init(os_sys_time_get());
#endif
#if F_APP_BLE_ENABLE
            if (gap_start_ok && clock_ok && !app_task_shutdown_blocks_new_business())
            {
                app_ble_power_on_wake();
            }
#endif
#if V0_IMU_FIFO_DRAIN_TEST && V1_IMU_FLASH_CAPTURE_ENABLE && \
            !ZY100_SRAM_ONLY_CAPTURE_TEST_ENABLE
            if (clock_ok && !app_task_shutdown_blocks_new_business() &&
                !app_task_device_gate_begin_runtime("direct_runtime_start"))
            {
                clock_ok = false;
            }
#endif
            if (clock_ok && !app_task_shutdown_blocks_new_business())
            {
                svc_app_watchdog_enable_active("direct_runtime_start");
                DBG_DIRECT("[APP_TASK] direct runtime gates open");
            }
        }

        {
            uint64_t runtime_ms = zy100_os_time_ms();
            bool b_critical = app_task_final_edge_b_critical_active();

            app_task_capture_battery_stats_log_poll((uint32_t)runtime_ms);
            app_task_main_direct_pre_event(runtime_ms, b_critical);
            if (app_task_main_event_drain(&event,
                                          &runtime_ms,
                                          &b_critical))
            {
                app_task_main_direct_post_event(runtime_ms, b_critical);
            }
            app_task_main_direct_loop_tail(runtime_ms,
                                           b_critical,
                                           &runtime_log_last_ms);
        }

        os_delay(1U);
    }
#endif
#endif
}

#if !(V0_IMU_FIFO_DRAIN_TEST && V1_IMU_FLASH_CAPTURE_ENABLE && \
      !ZY100_SRAM_ONLY_CAPTURE_TEST_ENABLE)
bool app_task_timeout_action_pending(void) { return false; }
bool app_task_timeout_action_ack(uint8_t conn_id, uint8_t seq,
    uint32_t generation, uint32_t token, uint64_t reason)
{
    (void)conn_id; (void)seq; (void)generation; (void)token; (void)reason;
    return false;
}

bool app_task_device_logic_ready(void)
{
    return !app_task_shutdown_blocks_new_business();
}

bool app_task_pairing_bonded_persisted(void)
{
    return true;
}

#endif

